const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const villarrica = ee.Geometry.Point([-71.935, -39.42]).buffer(5000); // 5km buffer around volcano

  // Target period
  const targetStart = '2021-12-01';
  const targetEnd = '2022-01-31';

  // Historical period (2000-2020 for Dec-Jan)
  const histStart = '2000-12-01';
  const histEnd = '2020-01-31';

  // 2. Data Acquisition - MODIS Snow Cover
  function getSnowCollection(startDate, endDate) {
    return ee.ImageCollection('MODIS/006/MOD10A1')
      .filterDate(startDate, endDate)
      .filter(ee.Filter.calendarRange(12, 1, 'month')) // Dec-Jan months only
      .select('NDSI_Snow_Cover');
  }

  // Get collections
  const targetCol = getSnowCollection(targetStart, targetEnd);
  const histCol = getSnowCollection(histStart, histEnd);

  // Check collection sizes
  const targetSize = targetCol.size().getInfo();
  const histSize = histCol.size().getInfo();

  console.log(`Target period (2021-22) images: ${targetSize}`);
  console.log(`Historical period images: ${histSize}`);

  if (targetSize === 0 || histSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate means
  const targetMean = targetCol.mean();
  const histMean = histCol.mean();

  // Check valid pixels
  const targetCount = targetMean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: villarrica,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDSI_Snow_Cover').getInfo();

  const histCount = histMean.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: villarrica,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDSI_Snow_Cover').getInfo();

  console.log(`Target valid pixels: ${targetCount}`);
  console.log(`Historical valid pixels: ${histCount}`);

  if (targetCount === 0 || histCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation - Get mean values
  const targetVal = targetMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: villarrica,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDSI_Snow_Cover').getInfo();

  const histVal = histMean.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: villarrica,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDSI_Snow_Cover').getInfo();

  console.log(`Target mean snow cover: ${targetVal?.toFixed(2)}%`);
  console.log(`Historical mean snow cover: ${histVal?.toFixed(2)}%`);

  // 5. Validation & Final Answer
  if (targetVal === null || histVal === null || 
      isNaN(targetVal) || isNaN(histVal) ||
      targetVal < 0 || targetVal > 100 || histVal < 0 || histVal > 100) {
    console.log("<answer>C3</answer>");
  } else if (targetVal > histVal) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
